import { useState } from 'react';
import './styles.css';

type AlgorithmType = 'classification' | 'regression' | 'clustering' | 'reinforcement';

interface Scenario {
  id: number;
  description: string;
  context: string;
  answer: AlgorithmType;
  explanation: string;
  hint: string;
}

const scenarios: Scenario[] = [
  {
    id: 1,
    description: 'A bank wants to flag potentially fraudulent transactions.',
    context: 'Financial services',
    answer: 'classification',
    explanation: 'This is classification—sorting transactions into "fraudulent" or "legitimate" categories.',
    hint: 'Think: is the output a label/category?'
  },
  {
    id: 2,
    description: 'An e-commerce site wants to predict how much a customer will spend next month.',
    context: 'Retail',
    answer: 'regression',
    explanation: 'This is regression—predicting a continuous number (dollar amount).',
    hint: 'Think: is the output a number?'
  },
  {
    id: 3,
    description: 'A streaming service wants to group users based on watching habits, without predefined categories.',
    context: 'Entertainment',
    answer: 'clustering',
    explanation: 'This is clustering—discovering natural groups in data without predefined labels.',
    hint: 'Think: are we discovering groups, or sorting into known ones?'
  },
  {
    id: 4,
    description: 'A game company wants to train an AI to play chess at grandmaster level.',
    context: 'Gaming',
    answer: 'reinforcement',
    explanation: 'This is reinforcement learning—learning optimal moves through trial and error with rewards for winning.',
    hint: 'Think: does the AI need to learn a strategy through practice?'
  },
  {
    id: 5,
    description: 'A hospital wants to predict which patients are at risk of readmission within 30 days.',
    context: 'Healthcare',
    answer: 'classification',
    explanation: 'This is classification—sorting patients into "high risk" or "low risk" categories.',
    hint: 'Think: is the output a label/category?'
  },
  {
    id: 6,
    description: 'A real estate company wants to estimate home values based on features like size and location.',
    context: 'Real estate',
    answer: 'regression',
    explanation: 'This is regression—predicting a continuous number (price).',
    hint: 'Think: is the output a number?'
  },
  {
    id: 7,
    description: 'A researcher wants to find patterns in ancient DNA samples to identify population groups.',
    context: 'Science',
    answer: 'clustering',
    explanation: 'This is clustering—discovering natural groupings without predefined categories.',
    hint: 'Think: are we discovering groups, or sorting into known ones?'
  },
  {
    id: 8,
    description: 'A warehouse wants to train robots to efficiently pick and pack items.',
    context: 'Logistics',
    answer: 'reinforcement',
    explanation: 'This is reinforcement learning—robots learn optimal movements through trial and reward.',
    hint: 'Think: does the AI need to learn a strategy through practice?'
  },
];

const algorithmInfo: Record<AlgorithmType, { icon: string; name: string; color: string }> = {
  classification: { icon: '📊', name: 'Classification', color: '#3B82F6' },
  regression: { icon: '📈', name: 'Regression', color: '#8B5CF6' },
  clustering: { icon: '🔮', name: 'Clustering', color: '#10B981' },
  reinforcement: { icon: '🎮', name: 'Reinforcement', color: '#F59E0B' },
};

export default function App() {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [score, setScore] = useState(0);
  const [answered, setAnswered] = useState(false);
  const [selectedAnswer, setSelectedAnswer] = useState<AlgorithmType | null>(null);
  const [showHint, setShowHint] = useState(false);
  const [history, setHistory] = useState<{ scenarioId: number; correct: boolean; answer: AlgorithmType }[]>([]);
  const [gameComplete, setGameComplete] = useState(false);

  const currentScenario = scenarios[currentIndex];
  const isCorrect = selectedAnswer === currentScenario?.answer;

  const handleAnswer = (answer: AlgorithmType) => {
    if (answered) return;
    setSelectedAnswer(answer);
    setAnswered(true);
    setShowHint(false);

    const correct = answer === currentScenario.answer;
    if (correct) setScore(s => s + 1);

    setHistory(h => [...h, { scenarioId: currentScenario.id, correct, answer }]);
  };

  const nextScenario = () => {
    if (currentIndex < scenarios.length - 1) {
      setCurrentIndex(i => i + 1);
      setAnswered(false);
      setSelectedAnswer(null);
      setShowHint(false);
    } else {
      setGameComplete(true);
    }
  };

  const restart = () => {
    setCurrentIndex(0);
    setScore(0);
    setAnswered(false);
    setSelectedAnswer(null);
    setShowHint(false);
    setHistory([]);
    setGameComplete(false);
  };

  const getMissedScenarios = () => {
    return history.filter(h => !h.correct).map(h => {
      const scenario = scenarios.find(s => s.id === h.scenarioId)!;
      return { ...scenario, userAnswer: h.answer };
    });
  };

  if (gameComplete) {
    const missed = getMissedScenarios();
    return (
      <div className="app">
        <h1>Algorithm Matcher</h1>
        <div className="results-screen">
          <div className="score-display">
            <div className="score-number">{score}/{scenarios.length}</div>
            <div className="score-label">Questions Correct</div>
          </div>

          <div className="performance">
            {score === scenarios.length && <p className="perfect">Perfect score! You've mastered algorithm matching.</p>}
            {score >= scenarios.length * 0.75 && score < scenarios.length && <p>Great job! You have a solid understanding.</p>}
            {score < scenarios.length * 0.75 && <p>Good effort! Review the explanations below to strengthen your understanding.</p>}
          </div>

          {missed.length > 0 && (
            <div className="missed-section">
              <h3>Review These</h3>
              {missed.map(m => (
                <div key={m.id} className="missed-item">
                  <p className="missed-scenario">{m.description}</p>
                  <p className="missed-answer">
                    You said: <span className="wrong">{algorithmInfo[m.userAnswer].name}</span>
                    {' → '}Correct: <span className="right">{algorithmInfo[m.answer].name}</span>
                  </p>
                  <p className="missed-explanation">{m.explanation}</p>
                </div>
              ))}
            </div>
          )}

          <button onClick={restart} className="restart-btn">Play Again</button>
        </div>

        <div className="cheat-sheet">
          <h3>Quick Reference</h3>
          <div className="cheat-grid">
            {Object.entries(algorithmInfo).map(([type, info]) => (
              <div key={type} className="cheat-item" style={{ borderColor: info.color }}>
                <span className="cheat-icon">{info.icon}</span>
                <span className="cheat-name">{info.name}</span>
                <span className="cheat-hint">
                  {type === 'classification' && 'Categories/labels'}
                  {type === 'regression' && 'Numbers'}
                  {type === 'clustering' && 'Discover groups'}
                  {type === 'reinforcement' && 'Learn strategies'}
                </span>
              </div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="app">
      <h1>Algorithm Matcher</h1>
      <p className="intro">Match each scenario to the best algorithm type.</p>

      <div className="progress">
        <div className="progress-bar">
          <div className="progress-fill" style={{ width: `${((currentIndex) / scenarios.length) * 100}%` }}></div>
        </div>
        <span className="progress-text">Question {currentIndex + 1} of {scenarios.length}</span>
        <span className="score-text">Score: {score}</span>
      </div>

      <div className="scenario-card">
        <div className="scenario-context">{currentScenario.context}</div>
        <p className="scenario-text">{currentScenario.description}</p>

        {!answered && !showHint && (
          <button className="hint-btn" onClick={() => setShowHint(true)}>Show Hint</button>
        )}
        {showHint && !answered && (
          <div className="hint">{currentScenario.hint}</div>
        )}
      </div>

      <div className="options">
        {(Object.keys(algorithmInfo) as AlgorithmType[]).map(type => {
          const info = algorithmInfo[type];
          let className = 'option-btn';
          if (answered) {
            if (type === currentScenario.answer) className += ' correct';
            else if (type === selectedAnswer) className += ' wrong';
          }
          return (
            <button
              key={type}
              className={className}
              onClick={() => handleAnswer(type)}
              disabled={answered}
              style={{ '--accent-color': info.color } as React.CSSProperties}
            >
              <span className="option-icon">{info.icon}</span>
              <span className="option-name">{info.name}</span>
            </button>
          );
        })}
      </div>

      {answered && (
        <div className={`feedback ${isCorrect ? 'correct' : 'incorrect'}`}>
          <div className="feedback-header">
            {isCorrect ? '✓ Correct!' : '✗ Not quite'}
          </div>
          <p className="feedback-explanation">{currentScenario.explanation}</p>
          <button onClick={nextScenario} className="next-btn">
            {currentIndex < scenarios.length - 1 ? 'Next Question' : 'See Results'}
          </button>
        </div>
      )}

      <div className="reflection">
        <h3>Remember</h3>
        <ul>
          <li><strong>Classification:</strong> Output is a category/label</li>
          <li><strong>Regression:</strong> Output is a number</li>
          <li><strong>Clustering:</strong> Discover unknown groups</li>
          <li><strong>Reinforcement:</strong> Learn strategy through practice</li>
        </ul>
      </div>
    </div>
  );
}

* { box-sizing: border-box; }
body { font-family: system-ui, -apple-system, sans-serif; background: #f8fafc; margin: 0; padding: 16px; }
.app { max-width: 600px; margin: 0 auto; }
h1 { font-size: 1.5rem; color: #1e293b; margin-bottom: 0.5rem; }
.intro { color: #64748b; margin-bottom: 1.5rem; font-size: 0.9rem; }

.progress { display: flex; align-items: center; gap: 12px; margin-bottom: 20px; flex-wrap: wrap; }
.progress-bar { flex: 1; min-width: 150px; height: 8px; background: #e2e8f0; border-radius: 4px; overflow: hidden; }
.progress-fill { height: 100%; background: #6366f1; border-radius: 4px; transition: width 0.3s ease; }
.progress-text, .score-text { font-size: 0.75rem; color: #64748b; }
.score-text { font-weight: 600; color: #6366f1; }

.scenario-card { background: white; border: 1px solid #e2e8f0; border-radius: 12px; padding: 20px; margin-bottom: 16px; }
.scenario-context { font-size: 0.7rem; color: #6366f1; text-transform: uppercase; letter-spacing: 0.05em; margin-bottom: 8px; }
.scenario-text { font-size: 1.1rem; color: #1e293b; margin: 0 0 12px 0; line-height: 1.5; }
.hint-btn { background: none; border: 1px dashed #cbd5e1; color: #64748b; padding: 6px 12px; border-radius: 6px; cursor: pointer; font-size: 0.75rem; }
.hint-btn:hover { border-color: #94a3b8; }
.hint { background: #fef3c7; padding: 10px 12px; border-radius: 6px; font-size: 0.8rem; color: #92400e; }

.options { display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; margin-bottom: 16px; }
.option-btn { background: white; border: 2px solid #e2e8f0; border-radius: 10px; padding: 14px; cursor: pointer; transition: all 0.2s; display: flex; flex-direction: column; align-items: center; gap: 6px; }
.option-btn:hover:not(:disabled) { border-color: var(--accent-color); background: #fafafa; }
.option-btn:disabled { cursor: default; }
.option-btn.correct { border-color: #22c55e; background: #dcfce7; }
.option-btn.wrong { border-color: #ef4444; background: #fee2e2; }
.option-icon { font-size: 1.5rem; }
.option-name { font-size: 0.875rem; font-weight: 500; color: #334155; }

.feedback { padding: 16px; border-radius: 10px; margin-bottom: 16px; }
.feedback.correct { background: #dcfce7; border: 1px solid #86efac; }
.feedback.incorrect { background: #fef3c7; border: 1px solid #fcd34d; }
.feedback-header { font-weight: 600; margin-bottom: 8px; }
.feedback.correct .feedback-header { color: #166534; }
.feedback.incorrect .feedback-header { color: #92400e; }
.feedback-explanation { font-size: 0.875rem; color: #334155; margin: 0 0 12px 0; }
.next-btn { background: #6366f1; color: white; border: none; padding: 10px 20px; border-radius: 8px; cursor: pointer; font-size: 0.875rem; }
.next-btn:hover { background: #4f46e5; }

.results-screen { background: white; border: 1px solid #e2e8f0; border-radius: 12px; padding: 24px; margin-bottom: 20px; text-align: center; }
.score-display { margin-bottom: 16px; }
.score-number { font-size: 3rem; font-weight: 700; color: #6366f1; }
.score-label { font-size: 0.875rem; color: #64748b; }
.performance { margin-bottom: 20px; }
.performance p { margin: 0; font-size: 1rem; color: #334155; }
.performance .perfect { color: #16a34a; }

.missed-section { text-align: left; margin-bottom: 20px; }
.missed-section h3 { font-size: 0.875rem; color: #dc2626; margin: 0 0 12px 0; }
.missed-item { background: #fef2f2; border: 1px solid #fecaca; border-radius: 8px; padding: 12px; margin-bottom: 8px; }
.missed-scenario { font-size: 0.875rem; color: #1e293b; margin: 0 0 6px 0; }
.missed-answer { font-size: 0.75rem; color: #64748b; margin: 0 0 6px 0; }
.missed-answer .wrong { color: #dc2626; }
.missed-answer .right { color: #16a34a; font-weight: 600; }
.missed-explanation { font-size: 0.75rem; color: #64748b; margin: 0; font-style: italic; }

.restart-btn { background: #6366f1; color: white; border: none; padding: 12px 24px; border-radius: 8px; cursor: pointer; font-size: 0.9rem; }
.restart-btn:hover { background: #4f46e5; }

.cheat-sheet { background: white; border: 1px solid #e2e8f0; border-radius: 12px; padding: 16px; margin-bottom: 20px; }
.cheat-sheet h3 { font-size: 0.875rem; color: #334155; margin: 0 0 12px 0; }
.cheat-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; }
.cheat-item { border: 2px solid; border-radius: 8px; padding: 10px; display: flex; flex-direction: column; align-items: center; gap: 4px; }
.cheat-icon { font-size: 1.25rem; }
.cheat-name { font-size: 0.8rem; font-weight: 600; color: #334155; }
.cheat-hint { font-size: 0.65rem; color: #64748b; }

.reflection { background: #f1f5f9; padding: 16px; border-radius: 12px; }
.reflection h3 { font-size: 0.875rem; color: #334155; margin: 0 0 8px 0; }
.reflection ul { margin: 0; padding-left: 0; list-style: none; }
.reflection li { font-size: 0.8rem; color: #64748b; margin-bottom: 4px; padding-left: 8px; }
